INSERT INTO homepage_content (id,merchant_id,content,created_at,updated_at,template_id) VALUES ('019f4cfb-2076-735f-9973-146708c2d325','00000000-0000-0000-0000-000000000001',E'{"hero":{"title":"SCENTS DESIGNED WITH INTENTION","ctaLink":"/shop","ctaText":"SHOP ALL","enabled":true,"eyebrow":"SOLID PERFUME","subtitle":"FORMULATED TO WORK WITH YOUR BODY CHEMISTRY.\\nCREATES COMPLIMENTS THAT LAST.","heroSlides":[],"backgroundImage":"/uploads/homepage/hero-01a028e5-64f2-70d8-ac98-bfef76fe84d7.webp","secondaryCtaLink":"/quiz","secondaryCtaText":"TAKE THE QUIZ"},"meta":{"enabled":true,"pageTitle":"Welcome to Our Store","pageDescription":"Discover amazing products curated just for you"},"aboutUs":{"title":"About Us","enabled":false,"titleAr":"من نحن","imageUrl":"","description":"Welcome to our store. We are passionate about bringing you the finest products.","descriptionAr":""},"marquee":{"text":"","enabled":false},"footerCta":{"title":"Ready to Start Shopping?","ctaLink":"/shop","ctaText":"Browse Products","enabled":true,"subtitle":"Join thousands of satisfied customers today"},"promoLine":{"text":"","textAr":""},"categories":{"title":"EXPLORE SCENTS","ctaLink":"/shop","ctaText":"VIEW ALL SCENTS","enabled":true,"subtitle":"Eight distinct scents. Each crafted with intention and precision. Find the one that speaks to you."},"newsletter":{"title":"Stay Updated","ctaText":"Subscribe","enabled":true,"subtitle":"Subscribe to our newsletter for exclusive deals and updates","privacyText":"We respect your privacy. Unsubscribe at any time.","placeholderText":"Enter your email address"},"valueProps":{"items":[{"icon":"clean","title":"CLEAN INGREDIENTS","description":"No alcohol. No parabens.\\nJust what you need."},{"icon":"pocket","title":"POCKET FRIENDLY","description":"Compact and durable.\\nMade to go anywhere."},{"icon":"clock","title":"LONG LASTING","description":"Solid formula.\\nScent that stays."},{"icon":"package","title":"FREE SHIPPING","description":"On all US orders\\nover $50."}],"enabled":true},"newArrivals":{"title":"New Arrivals","enabled":true,"viewAllLink":"/shop","viewAllText":"View All"},"promoBanner":{"text":"🎉 Special Offer: Get 20% off your first order!","enabled":false,"linkUrl":"/shop","linkText":"Shop Now"},"returnPolicy":{"intro":"We want you to love every Neckline fragrance. If something''s not right, we''re here to help.","steps":[{"icon":"package","title":"1. Return Window","titleAr":"1. فترة الإرجاع","description":"You may return any item within 14 days of delivery.","descriptionAr":"يمكنك إرجاع أي منتج خلال 14 يوماً من تاريخ التسليم."},{"icon":"bottle","title":"2. Eligible Items","titleAr":"2. المنتجات المؤهلة","description":"Items must be unused, unopened, and in original packaging.","descriptionAr":"يجب أن تكون المنتجات غير مستخدمة، غير مفتوحة، وفي عبوتها الأصلية."},{"icon":"receipt","title":"3. How to Return","titleAr":"3. كيفية الإرجاع","description":"Contact our support team via email or phone to initiate a return.","descriptionAr":"تواصل مع فريق الدعم عبر البريد الإلكتروني أو الهاتف لبدء عملية الإرجاع."},{"icon":"payment","title":"4. Refunds","titleAr":"4. المبالغ المستردة","description":"Once we receive and inspect your return, we''ll process your refund within 5–7 business days.","descriptionAr":"بمجرد استلامنا وفحص المرتجع، سنعالج استرداد المبلغ خلال 5–7 أيام عمل."}],"title":"Return Policy","enabled":true,"introAr":"نريدك أن تحب كل عطر من Neckline. إذا كان هناك أي مشكلة، نحن هنا لمساعدتك.","titleAr":"سياسة الإرجاع","footerMiddle":"or via our","footerPrefix":"Need help? We''re just an email away. Reach out to us at","supportEmail":"support@example.com","contactLinkUrl":"/contact","detailSections":[{"body":"For hygiene and safety reasons, we cannot accept returns on opened fragrance bottles. Gift cards and promotional items are also non-returnable.","title":"Non-Returnable Items","bodyAr":"لأسباب صحية وأمنية، لا نقبل إرجاع زجاجات العطور المفتوحة. بطاقات الهدايا والعروض الترويجية غير قابلة للإرجاع أيضاً.","titleAr":"منتجات غير قابلة للإرجاع"},{"body":"If your order arrives damaged or incorrect, please contact us within 48 hours of delivery with photos. We''ll arrange a replacement or refund as quickly as possible.","title":"Damaged or Wrong Items","bodyAr":"إذا وصل طلبك تالفاً أو غير صحيح، يرجى التواصل معنا خلال 48 ساعة من التسليم مع صور. سنرتب استبدالاً أو استرداداً في أسرع وقت ممكن.","titleAr":"منتجات تالفة أو خاطئة"}],"footerMiddleAr":"أو عبر","footerPrefixAr":"تحتاج مساعدة؟ نحن على بعد بريد إلكتروني. تواصل معنا على","contactLinkLabel":"Contact Us page","contactLinkLabelAr":"صفحة اتصل بنا"},"testimonials":{"items":[{"name":"Sarah Mitchell","nameAr":"نورة العتيبي","rating":5,"review":"Absolutely love the quality! Fast shipping and the product exceeded my expectations. Will definitely order again.","reviewAr":"من أفضل المنتجات اللي استخدمتها وبصراحة يستاهل أضعاف سعره، جودة عالية وتوصيل سريع."},{"name":"James Cooper","nameAr":"محمد المحسن","rating":5,"review":"Excellent shopping experience from start to finish. Customer service was outstanding and the product looks even better in person.","reviewAr":"تجربة شراء ممتازة من البداية للنهاية، خدمة عملاء رائعة والمنتج طلع أحلى من الصور."},{"name":"Emily Chen","nameAr":"فرح أحمد","rating":5,"review":"The attention to detail is remarkable. Premium packaging and the product itself is simply stunning. Highly recommended!","reviewAr":"تميز وإتقان سواء على مستوى التقديم أو جودة المنتجات، شكراً جزيلاً."},{"name":"David Wilson","nameAr":"مهند المري","rating":4,"review":"Fast delivery and solid quality. Returns were effortless when I needed to swap sizes — customer support made it painless.","reviewAr":"التوصيل سريع والجودة ممتازة، وتجربة الاستبدال كانت سهلة جداً بفضل خدمة العملاء."},{"name":"Olivia Taylor","nameAr":"ريم الشمري","rating":5,"review":"Everything was beautifully packaged and presented. The product quality is exceptional — worth every penny.","reviewAr":"كل شيء كان مرتباً ومغلفاً بشكل أنيق، والمنتج نفسه جودته عالية جداً."},{"name":"Marcus Reyes","nameAr":"خالد السبيعي","rating":4,"review":"Great value for the price. Shipping was a day faster than estimated and the item matched the photos exactly.","reviewAr":"قيمة ممتازة مقابل السعر، الشحن أسرع من المتوقع والمنتج مطابق تماماً للصور."}],"enabled":true},"contactBanner":{"slides":[],"enabled":true,"heading":"We Would Love To Hear From You","headingAr":"نود أن نسمع منك","description":"Have a question, feedback, or just want to say hello? Drop us a message and we''ll get back to you as soon as possible.","descriptionAr":"هل لديك سؤال أو ملاحظة أو تريد فقط أن تقول مرحبا؟ أرسل لنا رسالة وسنعود إليك في أقرب وقت ممكن.","directionsUrl":""},"bottomCarousel":{"slides":[],"enabled":true},"brandStatement":{"image":"/uploads/homepage/hero-019f88a0-d289-712d-b6f5-27eb5f5308d3.webp","title":"SMARTER SCENTS. BETTER FOR YOU.","enabled":true,"eyebrow":"Why solid is better","benefits":[{"icon":"briefcase","title":"PERFECTLY PORTABLE","description":"Compact and TSA-friendly.\\nTake your scent anywhere."},{"icon":"heart","title":"COMPLIMENT OPTIMIZED","description":"Subtle, skin-close scent\\nthat gets noticed for\\nall the right reasons."},{"icon":"badge","title":"STANDOUT SCENTS","description":"High-quality fragrance\\nblends that leave\\na lasting impression."},{"icon":"heat","title":"BODY-HEAT ACTIVATED","description":"Melts into your skin\\nand releases fragrance\\nthroughout the day."},{"icon":"ban","title":"PARABEN-FREE FORMULA","description":"Clean, non-toxic, and\\nsafe for everyday\\nuse on your skin."},{"icon":"globe","title":"NATURAL & RECYCLABLE","description":"Made with natural waxes\\nand plant-based oils.\\nBetter for you and\\nthe planet."}],"description":"Engineered for convenience. Crafted for performance."},"featuredProducts":{"title":"BEST SELLERS","enabled":true,"subtitle":"Check out our handpicked selection of trending products","viewAllLink":"/shop","viewAllText":""},"discountedProducts":{"title":"Offers","enabled":true,"viewAllLink":"/shop","viewAllText":"View All"},"faq":{"enabled":true,"eyebrow":"FAQ","eyebrowAr":"الأسئلة الشائعة","title":"Frequently Asked Questions","titleAr":"الأسئلة الشائعة","subtitle":"Everything you need to know about our products, orders, and more.","subtitleAr":"كل ما تحتاج معرفته عن منتجاتنا وطلباتك والمزيد.","items":[{"id":"faq-what-is","question":"What is Neckline solid perfume?","questionAr":"ما هو عطر Neckline الصلب؟","answer":"Neckline solid perfume is a premium, alcohol-free fragrance formulated with high-quality oils and waxes. It''s designed for a long-lasting, skin-close scent experience.","answerAr":"عطر Neckline الصلب عطر فاخر خالٍ من الكحول، مصنوع من زيوت وشمع عالية الجودة، ومصمّم ليمنحك رائحة قريبة من البشرة تدوم طويلاً."},{"id":"faq-how-to-use","question":"How do I use solid perfume?","questionAr":"كيف أستخدم العطر الصلب؟","answer":"Warm a small amount with your fingertip and press it onto your pulse points — wrists, neck, and behind the ears. Body heat activates the blend and releases the scent through the day.","answerAr":"دفّئ كمية صغيرة بطرف إصبعك وضعها على نقاط النبض — المعصمين والرقبة وخلف الأذنين. تنشّط حرارة الجسم التركيبة وتُطلق العطر طوال اليوم."},{"id":"faq-shipping-time","question":"How long does shipping take?","questionAr":"كم تستغرق مدة الشحن؟","answer":"Orders are dispatched within 1–2 business days. Domestic delivery usually takes 3–5 business days; international delivery takes 7–14 business days.","answerAr":"تُشحن الطلبات خلال يوم إلى يومي عمل. يستغرق التوصيل المحلي عادةً من 3 إلى 5 أيام عمل، والدولي من 7 إلى 14 يوم عمل."},{"id":"faq-returns","question":"Do you offer returns?","questionAr":"هل تقبلون الإرجاع؟","answer":"Yes. Unopened items can be returned within 14 days of delivery. Reach out to our support team and we''ll guide you through the process.","answerAr":"نعم. يمكن إرجاع المنتجات غير المفتوحة خلال 14 يوماً من التسليم. تواصل مع فريق الدعم وسنرشدك خلال العملية."},{"id":"faq-vegan","question":"Are your products vegan and cruelty-free?","questionAr":"هل منتجاتكم نباتية وخالية من القسوة على الحيوان؟","answer":"Every Neckline blend is vegan and never tested on animals. We use plant-based oils and natural waxes, with no parabens and no animal-derived ingredients.","answerAr":"كل تركيبات Neckline نباتية ولا تُختبر على الحيوانات. نستخدم زيوتاً نباتية وشمعاً طبيعياً، بلا بارابين وبلا أي مكوّنات حيوانية."},{"id":"faq-storage","question":"How should I store my solid perfume?","questionAr":"كيف أحفظ العطر الصلب؟","answer":"Keep the tin closed and stored somewhere cool and dry, away from direct sunlight. Stored that way the blend keeps its texture and strength for well over a year.","answerAr":"احفظ العلبة مغلقة في مكان بارد وجاف بعيداً عن أشعة الشمس المباشرة. بهذه الطريقة تحافظ التركيبة على قوامها وقوتها لأكثر من عام."},{"id":"faq-travel","question":"Can I travel with solid perfume?","questionAr":"هل يمكنني السفر بالعطر الصلب؟","answer":"Yes — that''s one of the best reasons to choose solid. There is no liquid, so it is carry-on friendly and won''t leak in a bag at altitude.","answerAr":"نعم — وهذا من أفضل أسباب اختيار العطر الصلب. فهو خالٍ من السوائل، ما يجعله مناسباً لحقيبة اليد ولا يتسرّب أثناء الطيران."},{"id":"faq-international","question":"Do you offer international shipping?","questionAr":"هل تشحنون دولياً؟","answer":"We ship to most countries worldwide. Available options, rates, and delivery estimates for your address are shown at checkout.","answerAr":"نشحن إلى معظم دول العالم. تظهر الخيارات المتاحة والأسعار ومدة التوصيل لعنوانك عند إتمام الطلب."}]}}','2026-07-10 17:02:34.08+00','2026-08-26 10:02:31.599597+00','landing-noir') ON CONFLICT DO NOTHING;

